    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Mustn''t and don''t have to';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Mustn''t and don''t have to','Distinguish prohibition from the absence of obligation.','Objective: Distinguish prohibition from the absence of obligation.
Content: Mustn''t means an action is prohibited. Don''t have to means an action is optional or unnecessary. They do not have the same meaning.
Examples:
- You mustn''t touch that switch.
- You don''t have to come early.
Common errors and corrections:
- You don''t have to park here. -> You mustn''t park here for a prohibition.
- He doesn''t have to wears a tie. -> He doesn''t have to wear a tie.
Guided practice: Decide whether each situation says no or not necessary before choosing mustn''t or don''t have to.
Summary: Mustn''t means do not do it; don''t have to means you may choose not to do it.','GRAMMAR',2,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Mustn''t and don''t have to','Distinguish prohibition from the absence of obligation.','Objective: Distinguish prohibition from the absence of obligation.
Content: Mustn''t means an action is prohibited. Don''t have to means an action is optional or unnecessary. They do not have the same meaning.
Examples:
- You mustn''t touch that switch.
- You don''t have to come early.
Common errors and corrections:
- You don''t have to park here. -> You mustn''t park here for a prohibition.
- He doesn''t have to wears a tie. -> He doesn''t have to wear a tie.
Guided practice: Decide whether each situation says no or not necessary before choosing mustn''t or don''t have to.
Summary: Mustn''t means do not do it; don''t have to means you may choose not to do it.','GRAMMAR',2,10,FALSE) RETURNING id INTO v_lesson_revision_id;
