    SELECT id INTO v_lesson_id FROM lessons WHERE topic_id=v_topic_id AND title='Can and could for permission and polite requests';
    IF v_lesson_id IS NULL THEN INSERT INTO lessons(topic_id,teacher_id,title,description,content,skill_type,order_index,status) VALUES(v_topic_id,v_teacher_id,'Can and could for permission and polite requests','Ask for permission and make polite requests with can and could.','Objective: Ask for permission and make polite requests with can and could.
Content: Can asks for permission in everyday situations. Could makes a more polite request. Both are followed by the base verb.
Examples:
- Can I use your pen?
- Could you open the window, please?
Common errors and corrections:
- Could you to help me? -> Could you help me?
- Can I to leave? -> Can I leave?
Guided practice: Choose can for ordinary permission and could when asking another person politely to do something.
Summary: Can is common for permission; could makes requests more polite; both take the base verb.','GRAMMAR',4,'DRAFT') RETURNING id INTO v_lesson_id; END IF;
    INSERT INTO lesson_revisions(topic_revision_id,source_lesson_id,teacher_id,title,description,content,skill_type,order_index,xp_reward,is_placement_test) VALUES(v_topic_revision_id,v_lesson_id,v_teacher_id,'Can and could for permission and polite requests','Ask for permission and make polite requests with can and could.','Objective: Ask for permission and make polite requests with can and could.
Content: Can asks for permission in everyday situations. Could makes a more polite request. Both are followed by the base verb.
Examples:
- Can I use your pen?
- Could you open the window, please?
Common errors and corrections:
- Could you to help me? -> Could you help me?
- Can I to leave? -> Can I leave?
Guided practice: Choose can for ordinary permission and could when asking another person politely to do something.
Summary: Can is common for permission; could makes requests more polite; both take the base verb.','GRAMMAR',4,10,FALSE) RETURNING id INTO v_lesson_revision_id;
